<?php
require_once __DIR__.'/../src/db.php';
$id=(int)($_GET['id']??0);$db=db();
$q=$db->prepare("SELECT * FROM tours WHERE id=? AND published=1");$q->execute([$id]);$tour=$q->fetch();
if(!$tour){http_response_code(404);exit('Tour not found');}
$q=$db->prepare("SELECT s.*,p.title panorama_title,p.description,p.image,p.preview,p.projection,p.stereo FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=? AND p.published=1 ORDER BY s.sort_order,s.id");$q->execute([$id]);$scenes=$q->fetchAll();
if(!$scenes){http_response_code(404);exit('Tour has no scenes');}
$start=$scenes[0];if(!empty($tour['start_scene_id']))foreach($scenes as $x)if((int)$x['id']===(int)$tour['start_scene_id']){$start=$x;break;}
$cover=$tour['cover']?:($start['preview']?:$start['image']);
$modes=[];foreach($scenes as $x){$modes[strtoupper($x['projection'])]=1;$modes[strtoupper($x['stereo'])]=1;}
?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#03070d"><title><?=htmlspecialchars($tour['title'])?> — MiniVR</title><link rel="stylesheet" href="/assets/app.css"></head><body><canvas id="space"></canvas><header><a class="brand" href="/">MINI<span>VR</span></a><nav><a href="/">ГЛАВНАЯ</a><a href="#route">МАРШРУТ</a></nav><div class="device-badge" id="device-badge">VR TOUR</div></header><main class="tour-page"><section class="tour-hero"><div class="tour-cover" style="background-image:url('<?=htmlspecialchars($cover)?>')"><div class="tour-cover-grid"></div><span class="tour-index">VR / <?=str_pad((string)$id,3,'0',STR_PAD_LEFT)?></span></div><div class="tour-intro"><div class="eyebrow">IMMERSIVE JOURNEY</div><h1><?=htmlspecialchars($tour['title'])?></h1><p><?=nl2br(htmlspecialchars($tour['description']?:'Виртуальная экскурсия MiniVR. Исследуйте пространство последовательно или переходите между сценами через интерактивные точки.'))?></p><div class="tour-facts"><div><b><?=count($scenes)?></b><span>СЦЕН</span></div><div><b><?=count($modes)?></b><span>ФОРМАТА</span></div><div><b>360</b><span>WEB / VR</span></div></div><div class="format-row"><?php foreach(array_keys($modes) as $m):?><span><?=$m?></span><?php endforeach;?></div><div class="hero-actions"><a class="primary launch" href="/viewer.php?id=<?=$start['panorama_id']?>&tour=<?=$id?>&scene=<?=$start['id']?>">▶ ЗАПУСТИТЬ ЭКСКУРСИЮ</a><a class="ghost" href="#route">ПОСМОТРЕТЬ МАРШРУТ</a></div><small class="tour-tip">Мышь / сенсор · Cardboard · WebXR</small></div></section><section id="route" class="route-section"><div class="section-title"><small>ROUTE / <?=count($scenes)?> SCENES</small><h2>Маршрут экскурсии</h2><p>Можно начать с первой сцены или открыть любую точку маршрута отдельно.</p></div><div class="route-grid"><?php foreach($scenes as $i=>$s):?><a class="route-card <?=$s['id']==$start['id']?'start':''?>" href="/viewer.php?id=<?=$s['panorama_id']?>&tour=<?=$id?>&scene=<?=$s['id']?>"><div class="route-preview" style="background-image:url('<?=htmlspecialchars($s['preview']?:$s['image'])?>')"><span><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><?php if($s['id']==$start['id']):?><i>START</i><?php endif;?></div><div><small><?=strtoupper(htmlspecialchars($s['projection']))?> · <?=strtoupper(htmlspecialchars($s['stereo']))?></small><h3><?=htmlspecialchars($s['title']?:$s['panorama_title'])?></h3><p><?=htmlspecialchars($s['description']?:'Открыть сцену виртуальной экскурсии')?></p></div></a><?php endforeach;?></div></section></main><footer><span>MINIVR / IMMERSIVE JOURNEY</span><span><?=count($scenes)?> SCENES · <?=implode(' · ',array_keys($modes))?></span><a href="/">← GALLERY</a></footer><script type="module" src="/assets/home.js"></script><?php require __DIR__.'/assets/music-player.php'; ?></body></html>